/**
 * obsidian/knowledge/derived-path.ts — helpers to identify chamba-generated
 * (derived) files in the vault.
 *
 * A "derived path" is a path whose file is generated by chamba and can be
 * regenerated by `reindex`. It covers:
 *   - `INDEX.md` at the vault root or any subfolder
 *   - `temas/<any-depth>/*.md` except `temas/VOCABULARIO.md`
 *   - `temas/*.base`
 *
 * A file is "chamba-generated" when its content proves it was emitted by
 * chamba (not written by a human):
 *   - `.md` files: frontmatter has `source: chamba` AND (`generated: true` OR the
 *     path matches an INDEX.md pattern — legacy INDEX.md files from before
 *     `generated: true` was added also count as generated).
 *   - `.base` files: comment line `# generated: true` AND text `source: chamba`.
 *
 * Pure TypeScript — no `node:` imports.
 */

// ─── isDerivedPathPattern ─────────────────────────────────────────────────────

/**
 * Return `true` when `path` (vault-relative, `/`-separated) matches the
 * pattern of a chamba-derived file:
 *   - `INDEX.md` (vault root)
 *   - `<any-folder>/INDEX.md`
 *   - `temas/<any>.md` (any depth) EXCEPT `temas/VOCABULARIO.md`
 *   - `temas/<name>.base` (only one level deep)
 */
export function isDerivedPathPattern(path: string): boolean {
  // INDEX.md at root or in any subfolder
  if (path === 'INDEX.md' || path.endsWith('/INDEX.md')) return true;

  if (!path.startsWith('temas/')) return false;

  const after = path.slice('temas/'.length);

  // temas/**/*.md but NOT temas/VOCABULARIO.md
  if (after.endsWith('.md') && path !== 'temas/VOCABULARIO.md') return true;

  // temas/*.base — only one level deep (no slash in the name part)
  if (after.endsWith('.base') && !after.includes('/')) return true;

  return false;
}

// ─── Frontmatter extraction helpers ──────────────────────────────────────────

function stripCR(line: string): string {
  return line.endsWith('\r') ? line.slice(0, -1) : line;
}

/** Extract raw frontmatter text (between `---` fences), or `''` if none. */
function extractFmText(content: string): string {
  const lines = content.split('\n');
  if (stripCR(lines[0] ?? '') !== '---') return '';
  for (let i = 1; i < lines.length; i++) {
    if (stripCR(lines[i] ?? '') === '---') {
      return lines.slice(1, i).join('\n');
    }
  }
  return '';
}

// ─── isChambaGenerated ────────────────────────────────────────────────────────

/**
 * Return `true` when `content` was generated by chamba (not written by a
 * human):
 *
 * - `.base` files: the first lines must contain `# generated: true` and
 *   `source: chamba` as comments.
 * - `.md` files: frontmatter must have `source: chamba` AND either
 *   `generated: true` (current format) OR the path is an `INDEX.md` pattern
 *   (legacy format — `source: chamba` alone is enough for INDEX.md files).
 *
 * @param path    - Vault-relative path of the file (used to determine format).
 * @param content - Full file content as a string.
 */
export function isChambaGenerated(path: string, content: string): boolean {
  if (path.endsWith('.base')) {
    // .base files use YAML comments to declare generation
    return content.includes('# generated: true') && content.includes('source: chamba');
  }

  const fm = extractFmText(content);

  // Check source: chamba
  const hasSource = /(?:^|\n)source:\s*chamba(?:\s|$)/.test(fm);
  if (!hasSource) return false;

  // Check generated: true
  const hasGenerated = /(?:^|\n)generated:\s*true(?:\s|$)/.test(fm);
  if (hasGenerated) return true;

  // Legacy INDEX.md: source: chamba without generated: true
  if (path === 'INDEX.md' || path.endsWith('/INDEX.md')) return true;

  return false;
}
